import { cn } from "@/lib/utils"

type Medium = "web" | "slide"
type SlideAgendaCopy = { heading: string; items: readonly string[] }

export function SlideAgenda({ copy, medium = "web" }: { copy: SlideAgendaCopy; medium?: Medium }) {
  const slide = medium === "slide"
  return (
    <section data-slot="slide-agenda" data-medium={medium} className={cn("flex flex-col justify-center gap-8 bg-background text-foreground", slide ? "aspect-video w-full overflow-hidden px-24 py-20" : "px-6 py-20 md:px-12")}>
      <h2 className={cn("font-heading font-semibold tracking-tight", slide ? "text-6xl" : "text-3xl")}>{copy.heading}</h2>
      <ol className={cn("grid gap-4 border-l border-border pl-8", slide ? "text-3xl" : "text-lg")}>
        {copy.items.map((item, index) => (
          <li key={index} className="marker:text-muted-foreground">{item}</li>
        ))}
      </ol>
    </section>
  )
}
